// Keep only the latest BME280 reading (no history needed)
let d = msg.payload;
if (typeof d === "string") { try { d = JSON.parse(d); } catch (e) { return null; } }
if (!d || typeof d !== "object") return null;

const t = Number(d.temperature), h = Number(d.humidity);
let p = Number(d.pressure);
if (!Number.isFinite(t) || !Number.isFinite(h) || h < 0 || h > 100) {
    node.warn("Ignoring bad sensor payload");
    return null;
}
if (!Number.isFinite(p)) p = null; else if (p > 20000) p = p / 100;   // Pa -> hPa

flow.set("sensor", { t: t, h: h, p: p, ts: Date.now() });
node.status({ fill: "green", shape: "dot", text: t.toFixed(1) + "°C  " + h.toFixed(0) + "%" });
return null;

// Builds the OpenWeatherMap "current weather" URL.
// Key and city come from this flow tab > Properties > Environment variables.
const KEY  = env.get("OWM_KEY");
const CITY = env.get("OWM_CITY") || "Chennai";
if (!KEY) {
    node.warn("OWM_KEY is empty. Set it in the flow tab's environment variables.");
    node.status({ fill: "red", shape: "ring", text: "no OWM_KEY" });
    return null;
}
msg.url = "https://api.openweathermap.org/data/2.5/weather?q=" + encodeURIComponent(CITY) +
          "&appid=" + encodeURIComponent(KEY) + "&units=metric";
return msg;

const r = msg.payload;
if (!r || Number(r.cod) !== 200 || !r.main) {
    node.warn("Weather problem: " + (r && r.message ? r.message : "no data"));
    node.status({ fill: "red", shape: "ring", text: "API error" });
    return null;
}
const w0 = (r.weather && r.weather[0]) || {};
flow.set("weather", {
    t: r.main.temp, h: r.main.humidity, p: r.main.pressure, feels: r.main.feels_like,
    clouds: r.clouds ? r.clouds.all : 0, wind: r.wind ? r.wind.speed : 0,
    desc: w0.description || "", main: w0.main || "", id: w0.id || 0,
    night: /n$/.test(w0.icon || "") || (r.sys && r.dt < r.sys.sunrise) || (r.sys && r.dt > r.sys.sunset),
    raining: ["Rain","Drizzle","Thunderstorm"].indexOf(w0.main) >= 0 || !!r.rain,
    city: r.name, ts: Date.now()
});
node.status({ fill: "green", shape: "dot", text: r.main.temp + "°C  " + (w0.description || "") });
return null;

// Builds the OpenWeatherMap 3-hourly forecast URL (8 steps = 24 h).
const KEY  = env.get("OWM_KEY");
const CITY = env.get("OWM_CITY") || "Chennai";
if (!KEY) {
    node.warn("OWM_KEY is empty. Set it in the flow tab's environment variables.");
    node.status({ fill: "red", shape: "ring", text: "no OWM_KEY" });
    return null;
}
msg.url = "https://api.openweathermap.org/data/2.5/forecast?q=" + encodeURIComponent(CITY) +
          "&appid=" + encodeURIComponent(KEY) + "&units=metric&cnt=8";
return msg;

const r = msg.payload;
if (!r || String(r.cod) !== "200" || !Array.isArray(r.list)) {
    node.warn("Forecast problem: " + (r && r.message ? r.message : "no data"));
    return null;
}
function ah(t, h) {
    const e = h / 100 * 6.112 * Math.exp(17.67 * t / (t + 243.5));
    return 216.7 * e / (273.15 + t);
}
const list = r.list.slice(0, 8).map(it => {
    const t = it.main.temp, h = it.main.humidity;
    const m = (it.weather && it.weather[0]) || {};
    const pop = it.pop || 0;
    return {
        ts: it.dt * 1000, t: t, h: h, p: it.main.pressure, ah: ah(t, h), pop: pop,
        rain: ["Rain", "Drizzle", "Thunderstorm"].indexOf(m.main) >= 0 || pop >= 0.5,
        desc: m.description || ""
    };
});
flow.set("forecast", { list: list, ts: Date.now() });
node.status({ fill: "green", shape: "dot", text: list.length + " steps" });
return null;

// Builds the JSON that the dashboard page polls (GET /board/data)
// Indoor numbers = latest sensor reading only. Outdoor numbers, outlook and pressure trend = OpenWeatherMap API.
function ah(t, h) {
    const e = h / 100 * 6.112 * Math.exp(17.67 * t / (t + 243.5));
    return 216.7 * e / (273.15 + t);
}
function rhFromAh(t, a) {
    const e = a * (273.15 + t) / 216.7;
    const es = 6.112 * Math.exp(17.67 * t / (t + 243.5));
    return Math.max(0, Math.min(100, e / es * 100));
}
function dp(t, h) {
    if (!Number.isFinite(t) || !Number.isFinite(h) || h <= 0 || h > 100) return null;
    const a = 17.62, b = 243.12;
    const g = Math.log(h / 100) + a * t / (b + t);
    return b * g / (a - g);
}
function emc(tC, rh) {   // Hailwood-Horrobin equilibrium moisture content of wood, %
    const T = tC * 9 / 5 + 32, h = rh / 100;
    const W  = 330 + 0.452 * T + 0.00415 * T * T;
    const K  = 0.791 + 4.63e-4 * T - 8.44e-7 * T * T;
    const K1 = 6.34 + 7.75e-4 * T - 9.35e-5 * T * T;
    const K2 = 1.09 + 2.84e-2 * T - 9.04e-5 * T * T;
    const Kh = K * h, q = K1 * K2 * Kh * Kh;
    return 1800 / W * (Kh / (1 - Kh) + (K1 * Kh + 2 * q) / (1 + K1 * Kh + q));
}
const f1 = v => v.toFixed(1);

const now = Date.now();
const s = flow.get("sensor"), w = flow.get("weather"), fc = flow.get("forecast");
const sLive = !!(s && now - s.ts < 180000);
const wLive = !!(w && now - w.ts < 30 * 60000);

const q = msg.req && msg.req.query ? msg.req.query.surface : undefined;
let surface = (q === undefined || q === "") ? 23 : Number(q);
if (!Number.isFinite(surface)) surface = 23;
surface = Math.max(10, Math.min(35, surface));

// ---------- derived values ----------
const D = {};
if (sLive) { D.idp = dp(s.t, s.h); D.iah = ah(s.t, s.h); D.margin = surface - D.idp; }
if (wLive) { D.odp = dp(w.t, w.h); D.oah = ah(w.t, w.h); }
if (sLive && wLive) { D.ahGain = D.iah - D.oah; D.tempDiff = s.t - w.t; D.rhDiff = s.h - w.h; D.dewDiff = D.idp - D.odp; }

// ---------- mold risk score (current reading only, max 6) ----------
let score = 0;
const factors = [];
let level = -1, headline = "Waiting for the indoor sensor", tone = "info";
if (sLive) {
    const hum = Math.round(s.h);
    if (s.h >= 80)      { score += 3; factors.push({ tone: "bad",  text: "Humidity is " + hum + "%, well above the 70% mold line." }); }
    else if (s.h >= 70) { score += 2; factors.push({ tone: "warn", text: "Humidity is " + hum + "%, above the 70% mold line." }); }
    else if (s.h >= 60) { score += 1; factors.push({ tone: "info", text: "Humidity is " + hum + "%, a little high." }); }

    if (D.idp >= 22) { score += 1; factors.push({ tone: "info", text: "Dew point is " + f1(D.idp) + "°C, so the air is very muggy." }); }

    if (D.margin <= 0)      { score += 2; factors.push({ tone: "bad",  text: "Surfaces at " + f1(surface) + "°C are below the dew point, so water is condensing." }); }
    else if (D.margin < 2)  { score += 1; factors.push({ tone: "warn", text: "Surfaces at " + f1(surface) + "°C are within 2°C of condensing." }); }

    const th = [2, 3, 5];
    const prev = flow.get("lvl") || 0;
    let lvl = 0;
    for (let i = 0; i < 3; i++) if (score >= th[i] - (prev > i ? 1 : 0)) lvl = i + 1;   // hysteresis
    flow.set("lvl", lvl);
    level = lvl;
    headline = ["Mold risk is low", "Worth watching", "Mold risk is rising", "Mold conditions are present"][lvl];
    tone = ["good", "info", "warn", "bad"][lvl];
    if (!factors.length) factors.push({ tone: "good", text: "Humidity is " + hum + "%, in a comfortable range." });
}

// ---------- ventilation verdict ----------
let vent = null;
if (sLive && wLive) {
    if (w.raining)               vent = { act: "Keep windows closed", why: "It is raining outside.", tone: "bad", code: "closed" };
    else if (D.ahGain >= 2)      vent = { act: "Open the windows", why: "Outdoor air holds " + f1(D.ahGain) + " g/m³ less water than the room.", tone: "good", code: "open" };
    else if (D.ahGain <= -2)     vent = { act: "Keep windows closed", why: "Outdoor air holds " + f1(-D.ahGain) + " g/m³ more water than the room.", tone: "bad", code: "closed" };
    else                         vent = { act: "Ventilation changes little", why: "Indoor and outdoor air hold about the same water.", tone: "info", code: "neutral" };
}

// ---------- API forecast: best window to ventilate ----------
let forecast = null, best = null;
if (fc && fc.list) {
    forecast = fc.list.map(x => {
        const gain = sLive ? D.iah - x.ah : null;
        const state = x.rain ? "rain" : gain === null ? "neutral" : gain >= 2 ? "open" : gain <= -2 ? "closed" : "neutral";
        return { ts: x.ts, t: x.t, h: x.h, ah: x.ah, pop: x.pop, desc: x.desc, gain: gain, state: state };
    });
    const cand = forecast.filter(x => x.state === "open").sort((a, b) => b.gain - a.gain);
    if (cand.length) { best = cand[0]; best.best = true; }
}

// ---------- outdoor pressure trend from the API forecast (hPa per 3 h) ----------
let outTrend = null;
if (fc && fc.list && fc.list.length >= 2 && Number.isFinite(fc.list[0].p) && Number.isFinite(fc.list[1].p)) {
    outTrend = fc.list[1].p - fc.list[0].p;
}

// ---------- instant diagnostics (no history needed) ----------
const ins = {};
if (sLive && wLive) {
    const gap = D.iah - D.oah;
    ins.gap = gap;
    if (gap >= 2)       { ins.source = "Wetter than outside"; ins.sourceWhy = "The room holds more water than the outdoor air. Open windows would dry it, unless it is raining."; }
    else if (gap <= -2) { ins.source = "Drier than outside"; ins.sourceWhy = "The outdoor air holds more water than the room, so letting it in would add moisture."; }
    else                { ins.source = "Balanced"; ins.sourceWhy = "Indoor and outdoor air hold about the same water."; }
    if (forecast && forecast.length) ins.outlook = forecast[0].ah - D.oah;
    ins.dry = { now: s.h, swap: rhFromAh(s.t, D.oah) };
}
if (sLive) {
    const target = emc(s.t, s.h);
    ins.wood = { target: target };
    ins.woodVerdict =
          target > 13   ? "Danger: swelling, glue joints and finish are at risk if this lasts"
        : target > 11   ? "Too humid: doors stick and instrument action rises"
        : target > 9.5  ? "Slightly humid: fine for furniture, not ideal for instruments"
        : target < 6    ? "Too dry: cracking risk"
        :                 "Safe range";
}

// ---------- recommendations ----------
const recs = [];
if (!sLive) recs.push({ tone: "bad", title: "Indoor sensor is offline", detail: "No reading on stm32/da for over 3 minutes. Check the STM32 board and its MQTT connection." });
if (!wLive) recs.push({ tone: "warn", title: "Outdoor weather is missing", detail: "Add your OpenWeatherMap key in the flow tab's environment variables (OWM_KEY). Until then only indoor advice is shown." });
if (vent) recs.push({ tone: vent.tone, title: vent.act, detail: vent.why });
if (sLive && s.h >= 70 && (!vent || vent.code !== "open")) {
    recs.push({ tone: "warn", title: "Dry the room mechanically", detail: "Outside air cannot dry the room right now. Run the AC in dry mode or use a dehumidifier." });
}
if (best && (!vent || vent.code !== "open")) {
    recs.push({ tone: "info", title: "Best time to open windows", detail: "The API forecast shows outdoor air holding about " + f1(best.gain) + " g/m³ less water around {t}.", ts: best.ts });
}
if (sLive && D.margin < 2) {
    recs.push({ tone: D.margin <= 0 ? "bad" : "warn", title: D.margin <= 0 ? "Surfaces are collecting water" : "Surfaces are close to condensing",
                detail: "Cold walls, windows or AC ducts at " + f1(surface) + "°C against a dew point of " + f1(D.idp) + "°C. Wipe them and keep air moving." });
}
if (ins.woodVerdict && ins.woodVerdict !== "Safe range") {
    const v = ins.woodVerdict;
    recs.push({ tone: v.startsWith("Danger") ? "warn" : v.startsWith("Slightly") ? "info" : "warn", title: "Wood and instruments", detail: v + "." });
}
if (typeof outTrend === "number") {
    if (outTrend <= -2)     recs.push({ tone: "info", title: "Pressure is forecast to fall", detail: "The API forecast shows outdoor pressure dropping " + f1(-outTrend) + " hPa over the next 3 hours. Rain may be on the way, so bring in laundry." });
    else if (outTrend >= 2) recs.push({ tone: "info", title: "Pressure is forecast to rise", detail: "The API forecast shows outdoor pressure rising " + f1(outTrend) + " hPa over the next 3 hours. Weather is likely clearing." });
}
if (!recs.length) recs.push({ tone: "good", title: "All clear", detail: "Nothing needs your attention right now." });
const pri = { bad: 0, warn: 1, info: 2, good: 3 };
recs.sort((a, b) => pri[a.tone] - pri[b.tone]);

msg.payload = {
    now: now, surface: surface,
    live: { s: sLive, w: wLive, sAge: s ? Math.round((now - s.ts) / 1000) : null, wAge: w ? Math.round((now - w.ts) / 1000) : null },
    sensor: sLive ? s : null,
    weather: wLive ? w : null,
    derived: D,
    risk: { score: score, max: 6, level: level, headline: headline, tone: tone, factors: factors },
    vent: vent, recs: recs, insight: ins, forecast: forecast, outTrend: outTrend
};
return msg;
